import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import type { Circuit } from '../circuit/model';
import examples from '../examples/circuits.json';
import { finalState } from './simulator';

// Generated by reference/generate.py from Qiskit's Statevector, already converted
// to Qanvas's bit order (q0 is the most significant bit of the index).
interface ReferenceCase {
  name: string;
  circuit: Circuit;
  state: { re: number[]; im: number[] };
}

const TOLERANCE = 1e-9;

function load(set: string): ReferenceCase[] {
  return JSON.parse(readFileSync(new URL(`../../reference/data/${set}.json`, import.meta.url), 'utf8'));
}

function maxDifference(circuit: Circuit, expected: ReferenceCase['state']): number {
  const actual = finalState(circuit);
  expect(actual.re.length).toBe(expected.re.length);
  let max = 0;
  for (let i = 0; i < expected.re.length; i++) {
    max = Math.max(max, Math.abs(actual.re[i] - expected.re[i]), Math.abs(actual.im[i] - expected.im[i]));
  }
  return max;
}

describe.each(['single-gate', 'examples', 'random'])('matches Qiskit: %s', (set) => {
  it.each(load(set))('$name', ({ circuit, state }) => {
    expect(maxDifference(circuit, state)).toBeLessThanOrEqual(TOLERANCE);
  });
});

it('has references for the current gallery circuits', () => {
  const references = Object.fromEntries(load('examples').map((c) => [c.name, c.circuit]));
  expect(references).toEqual(examples);
});

it('has 200 random circuits covering 1 to 12 qubits', () => {
  const random = load('random');
  expect(random).toHaveLength(200);
  expect(new Set(random.map((c) => c.circuit.qubits))).toEqual(new Set(Array.from({ length: 12 }, (_, i) => i + 1)));
});
